val scope = CoroutineScope(Dispatchers.Default)

repeat(10_000) { i ->
    scope.launch {
        delay(100)
        println("coroutine $i on ${Thread.currentThread().name}")
    }
}

// Thread count stays at the pool size (<= CPU count here)
// while 10,000 coroutines are alive — each is a few hundred bytes of heap.

suspend fun whoami(): String =
    Thread.currentThread().name

scope.launch(Dispatchers.Main) {
    // No suspension happened yet — still on main
    println(whoami())   // "main"

    // Internal dispatch is what changes threads
    val ioName = withContext(Dispatchers.IO) { whoami() }
    println(ioName)     // "DefaultDispatcher-worker-1"
}

scope.launch(Dispatchers.Default) {
    // Suspends: thread is free for other coroutines
    delay(1000)

    // Blocks: the worker thread parks for a second —
    // on a 4-core pool, 4 of these starve everything.
    Thread.sleep(1000)
}

// Expensive: a child coroutine + up to two dispatches per call
repeat(10_000) { i ->
    val v = withContext(Dispatchers.IO) { compute(i) }
    acc += v
}

// Cheap: one context switch, one coroutine
val result = withContext(Dispatchers.IO) {
    (0 until 10_000).sumOf { i -> compute(i) }
}

suspend fun <T> awaitResult(api: Api, request: Request): T =
    suspendCancellableCoroutine { cont ->
        val call = api.enqueue(request) { result ->
            cont.resume(result)           // exactly once
        }
        cont.invokeOnCancellation { call.cancel() }
    }

// With a resource that must be closed if the caller cancels:
cont.resume(response) { r -> r.close() }

scope.launch(Dispatchers.Main) {
    val data = withContext(Dispatchers.IO) {
        // resumes from a worker thread — the interceptor
        // re-posts back to Main before the block returns
        okHttpClient.execute(request)
    }
    render(data)   // runs on main
}

