scope.launch(Dispatchers.IO + CoroutineName("fetch")) {
    // Reads an element out of the context
    val name = coroutineContext[CoroutineName]?.name

    // Child inherits IO + name but gets its OWN Job
    launch {
        println(coroutineContext[Job] == this.coroutineContext[Job]) // false
    }
}

// Correct: the scope's root job is a supervisor
val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

scope.launch { throw RuntimeException("one child fails") }
scope.launch { println("still runs") }   // supervisor isolates the failure

// Wrong: the SupervisorJob is THIS coroutine's own job —
// it supervises nothing and failure still reaches the scope.
scope.launch(SupervisorJob()) { throw RuntimeException("bubbles up") }
